{-# LANGUAGE OverloadedStrings #-}
import Keiro.Workflow.Types (WorkflowId(..))
import Shikigami.Agent.Delegate (delegatedWorkflowId)
import Shikigami.Agent.Name (AgentName(..))
import Shikigami.AgentRun.Ledger (httpRunKey)
main :: IO ()
main = do
  print ("delegation coordinate collision", delegatedWorkflowId (WorkflowId "parent") "a:b" "c" == delegatedWorkflowId (WorkflowId "parent") "a" "b:c")
  print ("HTTP namespace collision", httpRunKey (AgentName "a:http:b") "c" == httpRunKey (AgentName "a") "b:http:c")
